alter table private.player_identity_states add column if not exists equipped_title text not null default 'none';
create or replace function private.player_unlocked_titles(p_user uuid,p_channel text)returns jsonb language plpgsql stable security definer set search_path=''as $$declare titles jsonb:='["first-inquiry"]'::jsonb;p private.player_progression_states;m private.player_mainline_states;a private.player_ascension_states;begin select * into p from private.player_progression_states where user_id=p_user and channel=p_channel;select * into m from private.player_mainline_states where user_id=p_user and channel=p_channel;select * into a from private.player_ascension_states where user_id=p_user and channel=p_channel;if coalesce(m.cleared_stage,0)>=18 then titles:=titles||'"nine-locks"'::jsonb;end if;if coalesce(p.body_level,0)>=229 then titles:=titles||'"body-ultimate"'::jsonb;end if;if private.server_all_books_mastered(p_user,p_channel)then titles:=titles||'"all-arts-master"'::jsonb;end if;if coalesce(a.title_id,'')<>''then titles:=titles||to_jsonb(a.title_id);end if;return titles;end$$;
create or replace function public.player_title_profile(p_channel text,p_action text default 'get',p_title text default null)returns jsonb language plpgsql security definer set search_path=''as $$declare uid uuid:=(select auth.uid());identity private.player_identity_states;titles jsonb;chosen text;begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test')or p_action not in('get','equip')then raise exception '稱號資料不正確';end if;select * into identity from private.player_identity_states where user_id=uid and channel=p_channel for update;if identity.user_id is null then raise exception '伺服器身分尚未建立';end if;titles:=private.player_unlocked_titles(uid,p_channel);if p_action='equip'then chosen:=coalesce(nullif(p_title,''),'none');if chosen<>'none'and not titles?chosen then raise exception '尚未取得此稱號';end if;update private.player_identity_states set equipped_title=chosen,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into identity;elsif identity.equipped_title<>'none'and not titles?identity.equipped_title then update private.player_identity_states set equipped_title='none',revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into identity;end if;return jsonb_build_object('unlocked',titles,'equipped',identity.equipped_title,'allArtsMastered',titles?'all-arts-master');end$$;
revoke all on function private.player_unlocked_titles(uuid,text)from public,anon,authenticated;
revoke all on function public.player_title_profile(text,text,text)from public,anon;
grant execute on function public.player_title_profile(text,text,text)to authenticated;
